const RUN_TOTAL = 9;
let monitorStarted=false, runDone=false, monTimer=null, agoTimer=null, shown=[], evIdx=0;
function pushEvent(){
  if(evIdx>=EVENTS.length){ finishRun(); return; }
  const e = {...EVENTS[evIdx], born:Date.now()}; shown.push(e); evIdx++;
  $('curFile').textContent = e.f + ' :: ' + e.fn;
  $('progNum').innerHTML = `${e.p} de ${RUN_TOTAL} funciones <span>(${Math.round(e.p/RUN_TOTAL*100)}%)</span>`;
  $('progBar').style.width = (e.p/RUN_TOTAL*100)+'%';
  $('evCount').textContent = shown.length;
  const [tag,cls] = TAG[e.a];
  const div = document.createElement('div');
  div.className = 'ev' + ({guard:' alert', watch:' alert watch', oracle:' alert oracle', stuck:' alert watch'}[e.a] || '');
  div.innerHTML = `<div class="node">${ICON[e.a]}</div><div class="box">
    <div class="hd"><span class="pill ${cls}" style="font-size:10.5px;padding:3px 8px">${tag}</span>
    <span class="file"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 3h9l4 4v14H6z"/></svg>${e.f} :: ${e.fn}</span>
    <span class="ago">◷ <span class="agoTxt">hace 0s</span></span></div>
    <div class="tx">${e.t}</div>
    ${e.guard?`<div class="guard ${e.a}"><span>⛉ ${e.guard[0]}</span><b>${e.guard[1]}</b></div>`:''}
  </div>`;
  $('timeline').appendChild(div); e.el = div.querySelector('.agoTxt');
  if(evIdx>=EVENTS.length) finishRun();
}
async function startMonitor(){
  if (!entornoListo) { toast(escHtml(entornoMotivo)); return; }
  if (window.pywebview && window.pywebview.api) {
    // Python verifica Docker (HU-13) y el entorno completo (EN-06) antes de iniciar.
    const r = await window.pywebview.api.start_run(projectPath, profile);
    if (r && r.status === 'docker_no_disponible') {
      toastError(escHtml(r.mensaje));
      actualizarSandbox();
      verificarEntorno();
      return;
    }
    if (r && r.status === 'blocked') { await verificarEntorno(); toastError(escHtml(r.motivo)); return; }
  }
  monitorStarted = true; runDone = false; evIdx = 0; shown = []; $('timeline').innerHTML='';
  document.querySelectorAll('#views a[data-v=exec],#views a[data-v=report]').forEach(a=>a.classList.add('off'));
  if($('nextbox')) $('nextbox').remove();
  $('ctxChip').className = 'chip amber'; $('ctxLbl').textContent = 'Analizando:';
  $('liveBtn').className = 'live'; $('liveTxt').innerHTML = 'LIVE<br>AGENTS'; paused = false;
  $('skipBtn').classList.remove('hide');
  go('monitor');
  pushEvent(); clearInterval(monTimer); monTimer = setInterval(pushEvent, 900);
  clearInterval(agoTimer);
  agoTimer = setInterval(() => shown.forEach(e => e.el.textContent = 'hace ' + Math.floor((Date.now()-e.born)/1000) + 's'), 1000);
}
function finishRun(){
  if(runDone) return; runDone = true; clearInterval(monTimer);
  $('ctxChip').className = 'chip done'; $('ctxLbl').textContent = 'Corrida #' + RUN_ID + ':'; $('curFile').textContent = 'completada';
  $('liveBtn').className = 'live done'; $('liveTxt').innerHTML = '✓ COMPLETADO';
  $('skipBtn').classList.add('hide');
  document.querySelectorAll('#views a[data-v=exec],#views a[data-v=report]').forEach(a=>a.classList.remove('off'));
  const d = document.createElement('div'); d.id='nextbox'; d.className='nextbox';
  d.innerHTML = `<span>Corrida #${RUN_ID} completada: ${RUN_TOTAL} funciones procesadas.</span><button class="btn" style="margin-left:auto" onclick="go('exec')">Ver ejecución de pruebas</button><button class="btn primary" onclick="go('report')">Ver reporte final →</button>`;
  $('timeline').after(d);
}
function skipRun(){ while(!runDone) pushEvent(); }
